import sys

# Re-define input with exactly 18 rows
input_grid = []
for i in range(18):
    if i == 2 or i == 6:
        row = [7, 7, 7, 7, 7, 5, 5, 5, 5]
    elif i == 3 or i == 4 or i == 5:
        row = [7, 5, 5, 5, 7, 5, 5, 5, 5]
    else:
        row = [5, 5, 5, 7, 5, 5, 5, 5, 5]
    input_grid.append(row)

print(f"Input grid has {len(input_grid)} rows")
for r, row in enumerate(input_grid[:3]):
    print(f"Row {r}: {row}")

output_grid = [[cell for cell in row] for row in input_grid]

visited = set()
components = []

for r in range(len(input_grid)):
    for c in range(len(input_grid[0])):
        if input_grid[r][c] == 7 and (r,c) not in visited:
            comp = [(r,c)]
            queue = [(r,c)]
            while queue:
                cur_r, cur_c = queue.pop(0)
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = cur_r + dr, cur_c + dc
                    if 0 <= nr < len(input_grid) and 0 <= nc < len(input_grid[0]):
                        if input_grid[nr][nc] == 7 and (nr,nc) not in visited:
                            visited.add((nr,nc))
                            comp.append((nr,nc))
                            queue.append((nr,nc))
            visited.add((r,c))
            components.append(comp)

print(f"\nFound {len(components)} connected components of 7s")
for i, comp in enumerate(components):
    comp_set = set(comp)
    rows = sorted([r for r,c in comp])
    cols = sorted([c for r,c in comp])
    h = max(rows) - min(rows) + 1
    w = max(cols) - min(cols) + 1
    bbox_area = h * w
    comp_density = len(comp_set) / bbox_area if bbox_area > 0 else 0
    print(f"Comp {i}: {len(comp)} cells, bounding box {h}x{w}, density={comp_density:.2f}")

    # For hollow frames, fill interior
    if comp_density < 0.95:  # Not a solid rectangle
        r_min, c_min = min(rows), min(cols)
        r_max, c_max = max(rows) + 1, max(cols) + 1

        for r in range(r_min, r_max):
            for c in range(c_min, c_max):
                if input_grid[r][c] == 5:
                    output_grid[r][c] = 4

print("\nOutput:")
for row in output_grid:
    print(' '.join(map(str, row)))

