    elif i == 3 or i == 4 or i == 5:
        row = [7, 5, 5, 5, 7, 5, 5, 5, 5]
    else:
        row = [5, 5, 5, 7, 5, 5, 5, 5, 5]
    input_grid.append(row)

output_grid = [[cell for cell in row] for row in input_grid]

# Find all 7-cells and their flood fill boundary
visited_7 = set()
for r in range(18):
    for c in range(9):
        if input_grid[r][c] == 7 and (r,c) not in visited_7:
            # BFS to find all connected 7s
            stack = [(r,c)]
            visited_7.add((r,c))
            while stack:
                cr, cc = stack.pop()
                for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                    nr, nc = cr + dr, cc + dc
                    if 0 <= nr < 18 and 0 <= nc < 9:
                        if input_grid[nr][nc] == 7 and (nr,nc) not in visited_7:
                            visited_7.add((nr,nc))
                            stack.append((nr,nc))

# Interior cells: background cells (5) that are enclosed by 7-component
# Using flood fill from outside
outside_reachable = set()
for r in range(18):
    for c in range(9):
        if input_grid[r][c] == 5 and (r,c) not in visited_7:
            # Flood fill all connected background cells from outside
            queue = [(r,c)]
            while queue:
                cur_r, cur_c = queue.pop(0)
                if (cur_r, cur_c) not in outside_reachable:
                    outside_reachable.add((cur_r, cur_c))
                    for dr, dc in [(-1,0),(1,0),(0,-1),(0,1)]:
                        nr, nc = cur_r + dr, cur_c + dc
                        if 0 <= nr < 18 and 0 <= nc < 9 and input_grid[nr][nc] == 5:
                            queue.append((nr,nc))

# Interior = background cells NOT reachable from outside
interior_cells = set()
for r in range(18):
    for c in range(9):
        if input_grid[r][c] == 5 and (r,c) not in outside_reachable:
            interior_cells.add((r,c))

print(f"Number of interior background cells: {len(interior_cells)}")
print("Interior cells:", sorted(interior_cells))

# Fill interior with 4s
