def find_json_files(base_dir, max_depth=10):
    """Find all JSON files within a depth limit"""
    results = []

    def walk(current_path, current_depth):
        if current_depth > max_depth:
            return
        try:
            entries = os.listdir(current_path)
        except PermissionError:
            return

        for entry in entries:
            full_path = os.path.join(current_path, entry)
            if os.path.isfile(full_path):
                if entry.endswith('.json'):
                    results.append((full_path, len(str(os.path.getsize(full_path)))))
            elif os.path.isdir(full_path):
                walk(full_path, current_depth + 1)

    walk(base_dir, 0)
    return results

